window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f3a6f85f15c1b8c0"]={"versions": [{"id": "FIG-f3a6f85f15c1b8c0", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-Diagramm) zur Veranschaulichung des Übertragungsmodus „Periodic“ (TM Periodic) eines I-PDUs im AUTOSAR COM-Modul (Communication) ohne Umschaltung des Transmission Mode Selectors (TMS). Der Kontext ist die zyklische I-PDU-Aussendung an die unterlagerte Schicht (PDU Router).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse (Abszisse)</strong>: Kontinuierlicher Zeitstrahl der I-PDU-Verarbeitung.\n</li><li><strong>Grüne Pfeile (vertikal nach unten gerichtet)</strong>: Periodische Sendezeitpunkte des I-PDUs durch AUTOSAR COM an den PDU Router.\n</li><li><strong>Intervall-Bemaßung (<code>tc</code>)</strong>: Zykluszeit / Periodendauer der zyklischen Übertragung (<code>ComTxModeTimePeriod</code>).\n</li><li><strong>Orangefarbene Blitzsymbole mit Beschriftung <code>v = x</code></strong>: Aufrufe zur Aktualisierung bzw. zum Senden eines Signals / Signalwerts (z. B. via <code>Com_SendSignal</code>) durch die Software-Komponente / obere Schicht.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das I-PDU wird in festen periodischen Zeitabständen <code>tc</code> zyklisch an den PDU Router übermittelt. Eintreffende Signalaktualisierungen (<code>v = x</code>), symbolisiert durch Blitzsymbole, lösen im reinen periodischen Übertragungsmodus keine sofortige Aussendung aus. Sie aktualisieren lediglich die internen Datenpuffer des I-PDUs; die eigentliche Übertragung erfolgt streng getaktet zu den regulären periodischen Zeitpunkten <code>tc</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Referenzszenario für die Konfiguration des Übertragungsmodus <code>PERIODIC</code> im AUTOSAR COM:</p>\n<ul class=\"fig-list\"><li>Signal-Aktualisierungen mit Transfer Property <code>PENDING</code> (oder <code>TRIGGERED</code> bei rein periodischem Modus ohne Ereignisübertragung) beeinflussen nicht das Sendezeitraster.\n</li><li>Die Zykluszeit <code>tc</code> korrespondiert mit dem Konfigurationsparameter <code>ComTxModeTimePeriod</code>.\n</li><li>Entwickler müssen beachten, dass Latenzen zwischen Signalbereitstellung (<code>Com_SendSignal</code>) und Busübertragung bis zu einem vollen Zyklus <code>tc</code> betragen können.\n</li></ul>"}, {"id": "FIG-ea1e72532f025ed7", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-Diagramm) zur Veranschaulichung des Übertragungsmodus „Periodic“ (TM Periodic) eines I-PDUs im AUTOSAR COM-Modul (Communication) ohne Umschaltung des Transmission Mode Selectors (TMS). Der Kontext ist die zyklische I-PDU-Aussendung an die unterlagerte Schicht (PDU Router).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse (Abszisse)</strong>: Kontinuierlicher Zeitstrahl der I-PDU-Verarbeitung.\n</li><li><strong>Grüne Pfeile (vertikal nach unten gerichtet)</strong>: Periodische Sendezeitpunkte des I-PDUs durch AUTOSAR COM an den PDU Router.\n</li><li><strong>Intervall-Bemaßung (<code>tc</code>)</strong>: Zykluszeit / Periodendauer der zyklischen Übertragung (<code>ComTxModeTimePeriod</code>).\n</li><li><strong>Orangefarbene Blitzsymbole mit Beschriftung <code>v = x</code></strong>: Aufrufe zur Aktualisierung bzw. zum Senden eines Signals / Signalwerts (z. B. via <code>Com_SendSignal</code>) durch die Software-Komponente / obere Schicht.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das I-PDU wird in festen periodischen Zeitabständen <code>tc</code> zyklisch an den PDU Router übermittelt. Eintreffende Signalaktualisierungen (<code>v = x</code>), symbolisiert durch Blitzsymbole, lösen im reinen periodischen Übertragungsmodus keine sofortige Aussendung aus. Sie aktualisieren lediglich die internen Datenpuffer des I-PDUs; die eigentliche Übertragung erfolgt streng getaktet zu den regulären periodischen Zeitpunkten <code>tc</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Referenzszenario für die Konfiguration des Übertragungsmodus <code>PERIODIC</code> im AUTOSAR COM:</p>\n<ul class=\"fig-list\"><li>Signal-Aktualisierungen mit Transfer Property <code>PENDING</code> (oder <code>TRIGGERED</code> bei rein periodischem Modus ohne Ereignisübertragung) beeinflussen nicht das Sendezeitraster.\n</li><li>Die Zykluszeit <code>tc</code> korrespondiert mit dem Konfigurationsparameter <code>ComTxModeTimePeriod</code>.\n</li><li>Entwickler müssen beachten, dass Latenzen zwischen Signalbereitstellung (<code>Com_SendSignal</code>) und Busübertragung bis zu einem vollen Zyklus <code>tc</code> betragen können.\n</li></ul>"}, {"id": "FIG-f01bbfa8f6aed231", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-Diagramm) zur Veranschaulichung des Übertragungsmodus „Periodic“ (TM Periodic) eines I-PDUs im AUTOSAR COM-Modul (Communication) ohne Umschaltung des Transmission Mode Selectors (TMS). Der Kontext ist die zyklische I-PDU-Aussendung an die unterlagerte Schicht (PDU Router).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse (Abszisse)</strong>: Kontinuierlicher Zeitstrahl der I-PDU-Verarbeitung.\n</li><li><strong>Grüne Pfeile (vertikal nach unten gerichtet)</strong>: Periodische Sendezeitpunkte des I-PDUs durch AUTOSAR COM an den PDU Router.\n</li><li><strong>Intervall-Bemaßung (<code>tc</code>)</strong>: Zykluszeit / Periodendauer der zyklischen Übertragung (<code>ComTxModeTimePeriod</code>).\n</li><li><strong>Orangefarbene Blitzsymbole mit Beschriftung <code>v = x</code></strong>: Aufrufe zur Aktualisierung bzw. zum Senden eines Signals / Signalwerts (z. B. via <code>Com_SendSignal</code>) durch die Software-Komponente / obere Schicht.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das I-PDU wird in festen periodischen Zeitabständen <code>tc</code> zyklisch an den PDU Router übermittelt. Eintreffende Signalaktualisierungen (<code>v = x</code>), symbolisiert durch Blitzsymbole, lösen im reinen periodischen Übertragungsmodus keine sofortige Aussendung aus. Sie aktualisieren lediglich die internen Datenpuffer des I-PDUs; die eigentliche Übertragung erfolgt streng getaktet zu den regulären periodischen Zeitpunkten <code>tc</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Referenzszenario für die Konfiguration des Übertragungsmodus <code>PERIODIC</code> im AUTOSAR COM:</p>\n<ul class=\"fig-list\"><li>Signal-Aktualisierungen mit Transfer Property <code>PENDING</code> (oder <code>TRIGGERED</code> bei rein periodischem Modus ohne Ereignisübertragung) beeinflussen nicht das Sendezeitraster.\n</li><li>Die Zykluszeit <code>tc</code> korrespondiert mit dem Konfigurationsparameter <code>ComTxModeTimePeriod</code>.\n</li><li>Entwickler müssen beachten, dass Latenzen zwischen Signalbereitstellung (<code>Com_SendSignal</code>) und Busübertragung bis zu einem vollen Zyklus <code>tc</code> betragen können.\n</li></ul>"}, {"id": "FIG-85d7f46d8ced25ec", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-Diagramm) zur Veranschaulichung des Übertragungsmodus „Periodic“ (TM Periodic) eines I-PDUs im AUTOSAR COM-Modul (Communication) ohne Umschaltung des Transmission Mode Selectors (TMS). Der Kontext ist die zyklische I-PDU-Aussendung an die unterlagerte Schicht (PDU Router).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse (Abszisse)</strong>: Kontinuierlicher Zeitstrahl der I-PDU-Verarbeitung, am rechten Pfeilende mit <code>t</code> gekennzeichnet.\n</li><li><strong>Grüne Pfeile (vertikal nach unten gerichtet)</strong>: Periodische Sendezeitpunkte des I-PDUs durch AUTOSAR COM an den PDU Router.\n</li><li><strong>Intervall-Bemaßung (<code>tc</code>)</strong>: Durchgängig zwischen allen aufeinanderfolgenden Sendezeitpunkten eingezeichnete Zykluszeit (<code>ComTxModeTimePeriod</code>).\n</li><li><strong>Rote offene Dreiecke (nach unten gerichtet) mit Beschriftung <code>v = x</code></strong>: Aufrufe zur Signalaktualisierung (z. B. via <code>Com_SendSignal</code>) durch die überlagerte Software-Schicht.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das I-PDU wird in festen periodischen Zeitabständen <code>tc</code> zyklisch an den PDU Router übermittelt. Eintreffende Signalaktualisierungen (<code>v = x</code>), symbolisiert durch Blitzsymbole, lösen im reinen periodischen Übertragungsmodus keine sofortige Aussendung aus. Sie aktualisieren lediglich die internen Datenpuffer des I-PDUs; die eigentliche Übertragung erfolgt streng getaktet zu den regulären periodischen Zeitpunkten <code>tc</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Referenzszenario für die Konfiguration des Übertragungsmodus <code>PERIODIC</code> im AUTOSAR COM:</p>\n<ul class=\"fig-list\"><li>Signal-Aktualisierungen mit Transfer Property <code>PENDING</code> (oder <code>TRIGGERED</code> bei rein periodischem Modus ohne Ereignisübertragung) beeinflussen nicht das Sendezeitraster.\n</li><li>Die Zykluszeit <code>tc</code> korrespondiert mit dem Konfigurationsparameter <code>ComTxModeTimePeriod</code>.\n</li><li>Entwickler müssen beachten, dass Latenzen zwischen Signalbereitstellung (<code>Com_SendSignal</code>) und Busübertragung bis zu einem vollen Zyklus <code>tc</code> betragen können.\n</li></ul>"}], "trans": [{"from": "FIG-f3a6f85f15c1b8c0", "to": "FIG-ea1e72532f025ed7", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ea1e72532f025ed7", "to": "FIG-f01bbfa8f6aed231", "fr": "R3.2.3", "tr": "R4.0.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f01bbfa8f6aed231", "to": "FIG-85d7f46d8ced25ec", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Symbolik für Sendeaufrufe / Signalaktualisierungen (<code>v = x</code>) von gezackten orangefarbenen Blitzsymbolen auf rote, nach unten weisende offene Dreiecksymbole umgestellt.\n</li><li>Bemaßung des periodischen Übertragungsintervalls <code>tc</code> über Doppelpfeile für alle aufeinanderfolgenden Übertragungszeitpunkte fortgeführt (fünf Intervalle statt zuvor zwei).\n</li><li>Zeitachse am rechten Pfeilende mit dem Formelzeichen <code>t</code> beschriftet.\n</li></ul>"}]};
